$('#torch-toggle').addEventListener('change',event=>command('torch',{enabled:event.target.checked}));$('#screen-mode-toggle').addEventListener('change',event=>command('screen-mode',{enabled:event.target.checked}));const sendScreenColors=()=>{clearTimeout(colorTimer);clearTimeout(planColorTimer);colorTimer=setTimeout(()=>{if(currentState?.status!=='running')command('screen-colors',{screenColor:$('#screen-color').value,accentColor:$('#accent-color').value});if(trackAnalysis&&localPlan?.beatMap)planColorTimer=setTimeout(generateMusicCues,80);else if(localPlan)planColorTimer=setTimeout(()=>sendShowPlan({...localPlan,cues:localPlan.cues.map(cue=>({...cue,screenColor:$('#screen-color').value,accentColor:$('#accent-color').value}))},{musicReady:trackReadyForPlan}),80)},100)};$('#screen-color').addEventListener('input',sendScreenColors);$('#accent-color').addEventListener('input',sendScreenColors);$('#protection-toggle').addEventListener('change',event=>{if(!event.target.checked){event.target.checked=true;openWarning()}else command('protection',{enabled:true})});$('#warning-cancel').addEventListener('click',closeWarning);$('#warning-confirm').addEventListener('click',()=>{closeWarning();command('protection',{enabled:false,acknowledgedRisk:true})});$('#warning-dialog').addEventListener('click',event=>{if(event.target.id==='warning-dialog')closeWarning()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#warning-dialog').classList.contains('hidden'))closeWarning()});
